// Throwaway probe for /api/nav-chat (deleted after run). Stands up an isolated
// express app on an ephemeral port with a known bearer key, mints a real
// nav-chat token, and exercises the route end-to-end against OpenAI.
import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

// Load OPENAI_API_KEY from .env into process.env BEFORE importing env.ts.
for (const line of readFileSync(".env", "utf8").split("\n")) {
  const m = /^([A-Z_]+)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}
console.log("OPENAI key present:", Boolean(process.env.OPENAI_API_KEY));

const express = (await import("express")).default;
const { generateAndWriteToken } = await import("./server/api/auth/token.js");
const { mintNavChatToken } = await import("./server/api/auth/viewToken.js");
const navChatRoutes = (await import("./server/api/routes/navChat.js")).default;

// Pin a known bearer key so the token module + our mint agree.
await generateAndWriteToken(join(tmpdir(), `navchat-probe-${Date.now()}.token`), "probe-bearer-key-0123456789abcdef");
const minted = mintNavChatToken("voice-nav");
if (!minted) throw new Error("mint failed");

const app = express();
app.use(express.json());
app.use(navChatRoutes);
const server = app.listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as { port: number }).port;
const url = `http://127.0.0.1:${port}/api/nav-chat`;
const auth = { Authorization: `Bearer ${minted.token}`, "Content-Type": "application/json" };

async function call(label: string, headers: Record<string, string>, body: unknown) {
  const res = await fetch(url, { method: "POST", headers, body: JSON.stringify(body) });
  const text = await res.text();
  console.log(`\n### ${label}\nHTTP ${res.status}\n${text}`);
}

// 1) auth rejection (no token)
await call("no token → expect 401", { "Content-Type": "application/json" }, { message: "こんにちは" });
// 2) validation (empty message)
await call("empty message → expect 400", auth, { message: "  " });
// 3) small talk (greeting) → expect { reply }
await call("greeting 'こんにちは' → expect reply", auth, { message: "こんにちは", context: { town: "日光市", dest: "男体山", etaMin: 42, mode: "車", time: "14:30" } });
// 4) chit-chat with context (ETA question)
await call("ETA question → expect reply using context", auth, { message: "あとどれくらいで着く？", context: { town: "日光市", dest: "男体山", etaMin: 42, mode: "車", time: "14:30" } });
// 5) operation intent → expect { action }
await call("'コンビニ寄って' → expect action json", auth, { message: "近くのコンビニ寄って", context: { town: "日光市", dest: "男体山", etaMin: 42, mode: "車" } });
// 6) music request → expect play_music action
await call("'なんか音楽かけて' → expect play_music", auth, { message: "なんか元気が出る音楽かけて", context: { town: "日光市", mode: "車" } });

server.close();

