// 第1層で会話系に落ちた発話をサーバー経由でLLMに投げ、短い相棒応答／操作アクションを得る。
// トークン未取得・失敗・タイムアウト時は定型文にフォールバック（会話を止めない）。
async function navChatReply(userText, fallbackType){
  if(!S.navChatToken || !S.navChatUrl){ botSay(cannedFor(fallbackType)); return; }
  let answered=false;
  // 応答が NAV_CHAT_FILLER_DELAY_MS 以内なら「えっと」を挟まない（速い時は不自然なので）
  const fillerTimer=setTimeout(()=>{ if(!answered) tts(T().filler); }, NAV_CHAT_FILLER_DELAY_MS);
  const ctrl=new AbortController();
  const to=setTimeout(()=>ctrl.abort(), NAV_CHAT_TIMEOUT_MS);
  try{
    const res=await fetch(S.navChatUrl,{ method:"POST",
      headers:{ "Authorization":"Bearer "+S.navChatToken, "Content-Type":"application/json" },
      body: JSON.stringify({ message:userText, context: buildNavContext() }), signal: ctrl.signal });
    answered=true; clearTimeout(fillerTimer);
    if(!res.ok) throw new Error("http "+res.status);
    const data=await res.json();
    if(data && typeof data.action==="string"){ handleLLMAction(data); return; }
    if(data && typeof data.reply==="string" && data.reply.trim()){ botSay(data.reply.trim()); return; }
    throw new Error("bad shape");
  }catch(e){
    answered=true; clearTimeout(fillerTimer);
    botSay(cannedFor(fallbackType));   // フォールバック（定型文）
  }finally{
    clearTimeout(to);
  }
}
function cannedFor(type){
  const m={ help:T().help, greet:T().greet, thanks:T().thanks, ack:T().ack, chat:T().chat };
  return m[type] || T().chat;
}
// LLMが返した操作アクションを既存関数にマッピング
function handleLLMAction(data){
  switch(data.action){
    case "set_destination": data.query ? searchDestination(data.query,{confirm:false}) : botSay(cannedFor("chat")); break;
    case "add_waypoint": data.query ? addWaypointByQuery(data.query) : botSay(cannedFor("chat")); break;
    case "start_nav": startNav(); break;
    case "stop_nav": stopNav(); break;
    case "repeat": repeatStep(); break;
    case "play_music": playMusicStub(data.mood); break;
    default: botSay(cannedFor("chat"));
  }
}
// 音楽リクエストは今回スタブ（Spotify連携は後日）。toast表示＋短い断り。
function playMusicStub(mood){
  toast((S.lang==="ja"?"🎵 音楽（準備中）":"🎵 Music (coming soon)")+(mood?(S.lang==="ja"?"："+mood:": "+mood):""));
  botSay(S.lang==="ja"?"音楽はまだ準備中なんです。":"Music isn't ready yet.");
}
// 任意の地名を経由地として追加（目的地未設定なら目的地にする）
function addWaypointByQuery(query){
  botSay(T().searching(query), false);
  const done=(loc,name)=>{
    if(!S.destination){ setDestinationCandidate(loc, name||query); return; }
    S.waypoints.unshift({loc, name:name||query});
    buildRoute(()=>botSay(T().detourAdd(name||query)));
  };
  if(S.places){
    const req={ query, ...(S.me?{location:S.me, radius:30000}:{}) };
    S.places.textSearch(req,(res,st)=>{
      if(st===google.maps.places.PlacesServiceStatus.OK && res && res[0]) done(res[0].geometry.location, res[0].name);
      else geocodeWaypoint(query, done);
    });
  } else geocodeWaypoint(query, done);
}
function geocodeWaypoint(query, done){
  if(!S.geocoder){ botSay(T().notFound(query)); return; }
  S.geocoder.geocode({address:query},(gr,gs)=>{
    (gs==="OK" && gr && gr[0]) ? done(gr[0].geometry.location, query) : botSay(T().notFound(query));
  });
}
// LLMへ渡す走行コンテキストを状態Sから組み立てる
function buildNavContext(){
  const d=new Date();
  const ctx={ time: d.getHours()+":"+String(d.getMinutes()).padStart(2,"0"),
              mode: (S.travelMode==="WALKING"?"徒歩":"車"), navOn:S.navOn };
  if(S.townName) ctx.town=S.townName;
  if(S.destName) ctx.dest=S.destName;
  const rem=routeRemaining();
  if(rem){ ctx.remainKm=rem.km; ctx.etaMin=rem.etaMin; }
  const recent=S.history.slice(0,-1).slice(-6).map(h=>({[h.role]:h.text}));
  if(recent.length) ctx.recent=recent;
  return ctx;
}
function routeRemaining(){
  if(!S.steps || !S.steps.length) return null;
  let dist=0, time=0;
  for(let i=Math.max(0,S.curStep); i<S.steps.length; i++){ dist+=S.steps[i].distance.value; time+=S.steps[i].duration.value; }
  return { km:+(dist/1000).toFixed(1), etaMin:Math.round(time/60) };
}
// 現在地の町名を逆ジオコードでキャッシュ（45秒スロットル）
function maybeUpdateTown(){
  if(!S.geocoder || !S.me) return;
  const now=Date.now();
  if(S.townName && now - S.townAt < 45000) return;
  S.townAt=now;
  S.geocoder.geocode({location:S.me},(gr,gs)=>{
    if(gs==="OK" && gr && gr[0]) S.townName=shortArea(gr[0].formatted_address);
  });
}

