// Throwaway probe for the existing /api/tts (deleted after run). Isolated app
// on an ephemeral port with a known bearer key + a real tts-scoped token.
import { readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

for (const line of readFileSync(".env", "utf8").split("\n")) {
  const m = /^([A-Z_]+)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}
console.log("OPENAI key present:", Boolean(process.env.OPENAI_API_KEY));

const express = (await import("express")).default;
const { generateAndWriteToken } = await import("./server/api/auth/token.js");
const { mintTtsToken } = await import("./server/api/auth/viewToken.js");
const ttsRoutes = (await import("./server/api/routes/tts.js")).default;

await generateAndWriteToken(join(tmpdir(), `tts-probe-${Date.now()}.token`), "probe-bearer-key-0123456789abcdef");
const minted = mintTtsToken("voice-nav");
if (!minted) throw new Error("mint failed");

const app = express();
app.use(express.json());
app.use(ttsRoutes);
const server = app.listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as { port: number }).port;
const url = `http://127.0.0.1:${port}/api/tts`;
const auth = { Authorization: `Bearer ${minted.token}`, "Content-Type": "application/json" };

async function jsonCall(label: string, headers: Record<string, string>, body: unknown) {
  const res = await fetch(url, { method: "POST", headers, body: JSON.stringify(body) });
  const ct = res.headers.get("content-type") || "";
  const text = ct.includes("application/json") ? await res.text() : `<${ct}, ${(await res.arrayBuffer()).byteLength} bytes>`;
  console.log(`\n### ${label}\nHTTP ${res.status}  ${text}`);
}

// 1) auth rejection
await jsonCall("no token → expect 401", { "Content-Type": "application/json" }, { text: "テスト" });
// 2) empty text
await jsonCall("empty text → expect 400", auth, { text: "  " });
// 3) over 500 chars
await jsonCall("501 chars → expect 413", auth, { text: "あ".repeat(501) });

// 4) valid short nav phrase → expect audio bytes; save + inspect magic bytes
async function audioCall(label: string, body: Record<string, unknown>, outfile: string) {
  const t0 = Date.now();
  const res = await fetch(url, { method: "POST", headers: auth, body: JSON.stringify(body) });
  const ct = res.headers.get("content-type") || "";
  const buf = Buffer.from(await res.arrayBuffer());
  writeFileSync(outfile, buf);
  const magic = buf.subarray(0, 3).toString("hex");
  console.log(`\n### ${label} (${Date.now() - t0}ms)\nHTTP ${res.status}  content-type=${ct}  bytes=${buf.length}  magic=${magic}  file=${outfile}`);
}
await audioCall("nav phrase 'この先300メートル、右方向です' (default tts-1/nova)", { text: "この先300メートル、右方向です" }, "/tmp/tts_nova.mp3");
await audioCall("voice=shimmer", { text: "まもなく目的地に到着します", voice: "shimmer" }, "/tmp/tts_shimmer.mp3");

server.close();

// Probe the key-unset path: /api/tts must return 503 (so the client falls back
// to Web Speech and navigation never breaks). We deliberately do NOT load .env
// and clear the var before importing env.ts (which snapshots process.env).
import { tmpdir } from "node:os";
import { join } from "node:path";

delete process.env.OPENAI_API_KEY;
console.log("OPENAI key present:", Boolean(process.env.OPENAI_API_KEY));

const express = (await import("express")).default;
const { generateAndWriteToken } = await import("./server/api/auth/token.js");
const { mintTtsToken } = await import("./server/api/auth/viewToken.js");
const ttsRoutes = (await import("./server/api/routes/tts.js")).default;

await generateAndWriteToken(join(tmpdir(), `tts-nokey-${Date.now()}.token`), "probe-bearer-key-0123456789abcdef");
const minted = mintTtsToken("voice-nav")!;

const app = express();
app.use(express.json());
app.use(ttsRoutes);
const server = app.listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as { port: number }).port;
const res = await fetch(`http://127.0.0.1:${port}/api/tts`, {
  method: "POST",
  headers: { Authorization: `Bearer ${minted.token}`, "Content-Type": "application/json" },
  body: JSON.stringify({ text: "この先300メートル、右方向です" }),
});
console.log(`\n### key unset → expect 503\nHTTP ${res.status}  ${await res.text()}`);
server.close();

