args.new_string:
// ブラウザ内蔵音声（Web Speech）。フォールバックの土台。
function webSpeak(text){
  if(!S.tts || !window.speechSynthesis) return;
  try{
    const u=new SpeechSynthesisUtterance(stripParens(text));
    const langKey=S.lang==="ja"?"ja":"en";
    u.lang = langKey==="ja" ? "ja-JP" : "en-US";
    const v=pickVoice(langKey);
    if(v){ u.voice=v; u.lang=v.lang; }
    // やわらかく落ち着いた読み上げ（速すぎ・平坦すぎを避ける）
    u.rate=0.98; u.pitch=1.02; u.volume=1;
    // ハンズフリー時に自分の声を拾わないよう発話区間を印付け
    u.onstart=()=>{ speaking=true; };
    const done=()=>{ speaking=false; ignoreUntil=Date.now()+700; };
    u.onend=done; u.onerror=done;
    speechSynthesis.cancel(); speechSynthesis.speak(u);
  }catch(e){ speaking=false; }
}

// 進行中の発話（Web Speech / OpenAI音声）を止める。新しい発話が来たら割り込む。
function stopSpeaking(){
  try{ if(window.speechSynthesis) speechSynthesis.cancel(); }catch(e){}
  if(S.curAudio){ try{ S.curAudio.pause(); }catch(e){} try{ URL.revokeObjectURL(S.curAudio.src); }catch(e){} S.curAudio=null; }
}

/* ---- IndexedDB: ナビ定型文のOpenAI音声をキャッシュ（走行中ゼロ遅延） ---- */
let ttsDbPromise=null;
function ttsDb(){
  if(ttsDbPromise) return ttsDbPromise;
  ttsDbPromise=new Promise((resolve,reject)=>{
    try{
      const req=indexedDB.open("mulmonavi-tts",1);
      req.onupgradeneeded=()=>{ req.result.createObjectStore("clips"); };
      req.onsuccess=()=>resolve(req.result);
      req.onerror=()=>reject(req.error);
    }catch(e){ reject(e); }
  });
  return ttsDbPromise;
}
function idbGet(key){
  return ttsDb().then(db=>new Promise((resolve,reject)=>{
    const r=db.transaction("clips","readonly").objectStore("clips").get(key);
    r.onsuccess=()=>resolve(r.result||null); r.onerror=()=>reject(r.error);
  })).catch(()=>null);
}
function idbPut(key,blob){
  return ttsDb().then(db=>new Promise((resolve,reject)=>{
    const r=db.transaction("clips","readwrite").objectStore("clips").put(blob,key);
    r.onsuccess=()=>resolve(); r.onerror=()=>reject(r.error);
  })).catch(()=>{});
}

// OpenAI TTS(/api/tts)へプロキシ経由でリクエスト → mp3 Blob
async function fetchTts(text, voice){
  const res=await fetch(S.ttsUrl,{ method:"POST",
    headers:{ "Authorization":"Bearer "+S.ttsToken, "Content-Type":"application/json" },
    body: JSON.stringify({ text: stripParens(text), voice, model:"tts-1", format:"mp3" }) });
  if(!res.ok) throw new Error("tts http "+res.status);   // 503(キー未設定)含め、Web Speechへ落とす
  return await res.blob();
}
// Blobを再生。再生開始で解決。ハンズフリーのエコー回避フラグも管理。
function playBlob(blob){
  return new Promise((resolve,reject)=>{
    const a=new Audio(URL.createObjectURL(blob));
    S.curAudio=a; speaking=true;
    const cleanup=()=>{ speaking=false; ignoreUntil=Date.now()+700; if(S.curAudio===a){ S.curAudio=null; } try{ URL.revokeObjectURL(a.src); }catch(e){} };
    a.onplaying=()=>resolve();
    a.onended=cleanup; a.onerror=()=>{ cleanup(); reject(new Error("audio play failed")); };
    a.play().catch(err=>{ cleanup(); reject(err); });
  });
}

// 3段構えの読み上げ入口。OpenAI TTS(ON+トークン有)→[定型文はIDBキャッシュ]→
// 失敗/未設定はWeb Speechへ自動フォールバック（ナビは絶対に止めない）。
// opts.cache=false で会話応答をキャッシュ対象外に。opts.sinceRecv で合計遅延計測。
async function tts(text, opts){
  if(!S.tts) return;
  const useOpenAI = S.openaiTts && S.ttsToken && S.ttsUrl;
  if(!useOpenAI){ webSpeak(text); return; }
  stopSpeaking();
  const cache = !opts || opts.cache !== false;
  const voice = S.openaiVoice || "nova";
  const t0 = performance.now();
  try{
    const key = S.lang+"|"+voice+"|"+text;
    let blob = cache ? await idbGet(key) : null;
    const hit = !!blob;
    if(!blob){ blob = await fetchTts(text, voice); if(cache) idbPut(key, blob); }
    await playBlob(blob);
    const gen = Math.round(performance.now()-t0);
    const total = (opts && opts.sinceRecv!=null) ? " total(recv→play)="+Math.round(performance.now()-opts.sinceRecv)+"ms" : "";
    console.log(`[MulmoNavi TTS] ${hit?"cache-hit":"openai"} play-start=${gen}ms${total} "${String(text).slice(0,24)}"`);
  }catch(e){
    console.log("[MulmoNavi TTS] fallback→WebSpeech:", (e&&e.message)||e);
    webSpeak(text);   // 不達・503・再生失敗 → 内蔵音声で継続
  }
}

