  // 応答が NAV_CHAT_FILLER_DELAY_MS 以内なら「えっと」を挟まない（速い時は不自然なので）
  const fillerTimer=setTimeout(()=>{ if(!answered) tts(T().filler); }, NAV_CHAT_FILLER_DELAY_MS);
  const ctrl=new AbortController();
  const to=setTimeout(()=>ctrl.abort(), NAV_CHAT_TIMEOUT_MS);
  try{
