// メッセージ末尾に、実際に鳴ったエンジンの小さなバッジを付ける（可視化）
function markEngine(el, kind){
  if(!el) return;
  let b=el.querySelector(".eng");
  if(!b){ b=document.createElement("span"); b.className="eng"; el.appendChild(b); }
  b.dataset.kind=kind;
  b.textContent = kind==="openai" ? "OpenAI" : kind==="cache" ? "OpenAI⚡" : "内蔵";
}
// エンジンが切り替わったら一度だけトーストで知らせる
function noteEngine(kind){
