  return avg;
}
const a1 = await bench("tts-1");
const a2 = await bench("tts-1-hd");
console.log(`\nΔ(hd - 1) avg = ${a2 - a1}ms  (${(((a2 - a1) / a1) * 100).toFixed(0)}% ${a2 >= a1 ? "slower" : "faster"})`);
