async function navChatReply(userText, fallbackType){
  if(!S.navChatToken || !S.navChatUrl){ botSay(cannedFor(fallbackType)); return; }
  let answered=false;
  // 応答が NAV_CHAT_FILLER_DELAY_MS 以内なら「えっと」を挟まない（速い時は不自然）。
  // フィラーは体感待ちの緩和が目的なので、TTSモードに関わらず即時のWeb Speechで発話。
  const fillerTimer=setTimeout(()=>{ if(!answered) webSpeak(T().filler); }, NAV_CHAT_FILLER_DELAY_MS);
  const ctrl=new AbortController();
  const to=setTimeout(()=>ctrl.abort(), NAV_CHAT_TIMEOUT_MS);
  const tReq=performance.now();
  try{
    const res=await fetch(S.navChatUrl,{ method:"POST",
      headers:{ "Authorization":"Bearer "+S.navChatToken, "Content-Type":"application/json" },
      body: JSON.stringify({ message:userText, context: buildNavContext() }), signal: ctrl.signal });
    answered=true; clearTimeout(fillerTimer);
    if(!res.ok) throw new Error("http "+res.status);
    const data=await res.json();
    const tRecv=performance.now();
    console.log(`[MulmoNavi] nav-chat net=${Math.round(tRecv-tReq)}ms`);
    if(data && typeof data.action==="string"){ handleLLMAction(data); return; }
    if(data && typeof data.reply==="string" && data.reply.trim()){
      // 応答受信と同時にTTS生成を開始（直列待ちを避ける）。会話応答はキャッシュしない。
      botSay(data.reply.trim(), true, { cache:false, sinceRecv:tRecv }); return;
    }
    throw new Error("bad shape");
  }catch(e){
    answered=true; clearTimeout(fillerTimer);
    botSay(cannedFor(fallbackType));   // フォールバック（定型文）
  }finally{
    clearTimeout(to);
  }
}

