import { readFileSync, writeFileSync } from "node:fs";
for (const line of readFileSync(".env", "utf8").split("\n")) {
  const m = /^([A-Z_]+)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}
const KEY = process.env.OPENAI_API_KEY!;
const SENTENCE = "300メートル先、右方向です。その後、国道120号線を直進します。";
const JA_INSTRUCTIONS = "日本語ネイティブのアナウンサーのように、落ち着いて明瞭に、自然なイントネーションで丁寧に読み上げてください。英語訛りにしないこと。";
const VOICES = ["alloy", "echo", "fable", "onyx", "nova", "shimmer", "coral", "sage", "ash"];

async function gen(model: string, voice: string, instructions?: string): Promise<string> {
  const body: Record<string, unknown> = { model, voice, input: SENTENCE, response_format: "mp3" };
  if (instructions) body.instructions = instructions;
  const res = await fetch("https://api.openai.com/v1/audio/speech", {
    method: "POST",
    headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`${model}/${voice} HTTP ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const b64 = Buffer.from(await res.arrayBuffer()).toString("base64");
  return `data:audio/mpeg;base64,${b64}`;
}

const rows: string[] = [];
// Reference: current model
console.log("gen reference tts-1-hd/shimmer ...");
try { rows.push(row("参考（現行）", "tts-1-hd", "shimmer", await gen("tts-1-hd", "shimmer"))); } catch (e) { console.log(String(e)); }
try { rows.push(row("参考（現行）", "tts-1-hd", "nova", await gen("tts-1-hd", "nova"))); } catch (e) { console.log(String(e)); }
// Primary: gpt-4o-mini-tts with JA instructions, all 9 voices
for (const v of VOICES) {
  console.log("gen gpt-4o-mini-tts/" + v + " ...");
  try { rows.push(row("gpt-4o-mini-tts（日本語指示）", "gpt-4o-mini-tts", v, await gen("gpt-4o-mini-tts", v, JA_INSTRUCTIONS))); }
  catch (e) { console.log(String(e)); rows.push(rowErr("gpt-4o-mini-tts", v, String(e))); }
}

function row(group: string, model: string, voice: string, src: string): string {
  return `<div class="card"><div class="meta"><span class="grp">${group}</span><b>${voice}</b><span class="mdl">${model}</span></div><audio controls preload="none" src="${src}"></audio></div>`;
}
function rowErr(model: string, voice: string, err: string): string {
  return `<div class="card err"><div class="meta"><b>${voice}</b><span class="mdl">${model}</span></div><div>生成失敗: ${err.replace(/</g, "&lt;")}</div></div>`;
}

