import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
for (const line of readFileSync(".env", "utf8").split("\n")) {
  const m = /^([A-Z_]+)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}
const express = (await import("express")).default;
const { generateAndWriteToken } = await import("./server/api/auth/token.js");
const { mintTtsToken } = await import("./server/api/auth/viewToken.js");
const ttsRoutes = (await import("./server/api/routes/tts.js")).default;
await generateAndWriteToken(join(tmpdir(), `instr-${Date.now()}.token`), "probe-bearer-key-0123456789abcdef");
const minted = mintTtsToken("voice-nav")!;
const app = express(); app.use(express.json()); app.use(ttsRoutes);
const server = app.listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as { port: number }).port;
const auth = { Authorization: `Bearer ${minted.token}`, "Content-Type": "application/json" };
const url = `http://127.0.0.1:${port}/api/tts`;
const text = "300メートル先、右方向です。その後、国道120号線を直進します。";
const JA = "日本語ネイティブのアナウンサーのように、落ち着いて明瞭に、自然なイントネーションで読み上げてください。英語訛りにしないこと。";
async function hit(label: string, body: object) {
  const t0 = Date.now();
  const res = await fetch(url, { method: "POST", headers: auth, body: JSON.stringify(body) });
  const ct = res.headers.get("content-type") || "";
  const size = ct.includes("audio") ? (await res.arrayBuffer()).byteLength : 0;
  const txt = ct.includes("audio") ? "" : (await res.text()).slice(0, 120);
  console.log(`${label}: HTTP ${res.status} ${ct} ${size ? size + " bytes" : txt} ${Date.now() - t0}ms`);
}
// 1) gpt-4o-mini-tts + JA instructions (nova) → should be 200 audio
await hit("gpt-4o-mini-tts/nova +instr", { text, voice: "nova", model: "gpt-4o-mini-tts", instructions: JA });
// 2) instructions sent to tts-1-hd → server drops it → should still be 200 (no upstream 400)
await hit("tts-1-hd +instr(dropped) ", { text, voice: "shimmer", model: "tts-1-hd", instructions: JA });
server.close();

