  // 各 final result を「このrecognizerで」一度だけ処理する。continuous認識では
  // 同一resultに対し onresult が複数回発火することがあり、二重発火の原因になる。
  r._done=0;
  r.onresult=e=>{
    for(let i=e.resultIndex; i<e.results.length; i++){
      const res=e.results[i];
      if(!res || !res.isFinal) continue;
      if(i < r._done) continue;   // 既に処理済みのindex → 無視（二重発火防止）
      r._done = i+1;
