  "- 操作意図を検出したら文章でなくJSONのみ返す:",'  {"action":"set_destination","query":"..."}',
  '  {"action":"add_waypoint","query":"..."}','  {"action":"stop_nav"} {"action":"start_nav"} {"action":"repeat"}',
  '  {"action":"play_music","mood":"..."}',"- 雑談は気さくに短く。","- contextの走行状況を使う","","例:",
  'ドライバー: セブン寄りたいんだけど → {"action":"add_waypoint","query":"セブンイレブン"}',
  'ドライバー: やっぱり東京駅に変更で → {"action":"set_destination","query":"東京駅"}',
  'ドライバー: 静かな曲が聴きたいな → {"action":"play_music","mood":"静かで落ち着いた"}',
].join("\n");
const MIN_SYS = "あなたはカーナビの相棒。context.langの言語で1文・短く返す。操作意図はJSONのみ。";

async function chat(sys: string, maxTok: number) {
  const t0 = Date.now();
  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model: "gpt-4o-mini", max_tokens: maxTok, temperature: 0.7,
      messages: [{ role: "system", content: sys }, { role: "user", content: "あとどれくらいで着く？" }],
      // include a small context like the app does
    }),
  });
  await res.json();
  return Date.now() - t0;
}

async function ttsBreakdown(model: string, text: string) {
  const t0 = Date.now();
  const res = await fetch("https://api.openai.com/v1/audio/speech", {
    method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model, voice: "nova", input: text, response_format: "mp3",
      ...(model === "gpt-4o-mini-tts" ? { instructions: "日本語ネイティブの自然な発音で明瞭に。" } : {}) }),
  });
  const reader = res.body!.getReader();
  let ttfb = 0, bytes = 0, chunks = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    if (!ttfb) ttfb = Date.now() - t0;
    bytes += value.length; chunks++;
  }
  const full = Date.now() - t0;
  console.log(`  ${model.padEnd(15)} TTFB=${ttfb}ms  full=${full}ms  bytes=${bytes} chunks=${chunks}  (stream-gain≈${full - ttfb}ms)`);
}

console.log("=== nav-chat (gpt-4o-mini chat) round trip ===");
for (const [lbl, sys, mt] of [["full-prompt/80", FULL_SYS, 80], ["full-prompt/40", FULL_SYS, 40], ["min-prompt/80", MIN_SYS, 80]] as const) {
  const runs: number[] = [];
  for (let i = 0; i < 3; i++) runs.push(await chat(sys, mt));
  console.log(`  ${String(lbl).padEnd(16)} runs=[${runs.join(", ")}]ms avg=${Math.round(runs.reduce((a, b) => a + b) / 3)}ms`);
}
console.log("\n=== TTS breakdown (streaming, nav phrase) ===");
const PHRASE = "300メートル先、右方向です。その後、国道120号線を直進します。";
await ttsBreakdown("gpt-4o-mini-tts", PHRASE);
await ttsBreakdown("tts-1-hd", PHRASE);
await ttsBreakdown("tts-1", PHRASE);

