const minted = mintNavChatToken("voice-nav")!;
const app = express(); app.use(express.json()); app.use(navChatRoutes);
const server = app.listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as { port: number }).port;
const url = `http://127.0.0.1:${port}/api/nav-chat`;
const auth = { Authorization: `Bearer ${minted.token}`, "Content-Type": "application/json" };
async function call(label: string, message: string, ctx: object) {
  const t0 = Date.now();
  const res = await fetch(url, { method: "POST", headers: auth, body: JSON.stringify({ message, context: ctx }) });
  console.log(`${label} (${Date.now() - t0}ms): ${await res.text()}`);
}
const ja = { lang: "ja", town: "日光市", dest: "男体山", etaMin: 42, mode: "車" };
await call("JA chat  ", "ありがとう", ja);
await call("JA ETA   ", "あとどれくらいで着く？", ja);
await call("JA long  ", "この辺で有名な観光地ってある？", ja);
