// ブラウザ内蔵音声（Web Speech）。フォールバックの土台。
function webSpeak(text){
  if(!S.tts || !window.speechSynthesis) return;
  try{
    const u=new SpeechSynthesisUtterance(stripParens(text));
    const langKey=S.lang==="ja"?"ja":"en";
    u.lang = langKey==="ja" ? "ja-JP" : "en-US";
    const v=pickVoice(langKey);
    if(v){ u.voice=v; u.lang=v.lang; }
    // やわらかく落ち着いた読み上げ（速すぎ・平坦すぎを避ける）
    u.rate=0.98; u.pitch=1.02; u.volume=1;
    // ハンズフリー時に自分の声を拾わないよう発話区間を印付け
    u.onstart=()=>{ speaking=true; };
    const done=()=>{ speaking=false; ignoreUntil=Date.now()+700; };
    u.onend=done; u.onerror=done;
    speechSynthesis.cancel(); speechSynthesis.speak(u);
  }catch(e){ speaking=false; }
}

// 進行中の発話（Web Speech / OpenAI音声）を止める。新しい発話が来たら割り込む。
function stopSpeaking(){
  try{ if(window.speechSynthesis) speechSynthesis.cancel(); }catch(e){}
  if(S.curAudio){ try{ S.curAudio.pause(); }catch(e){} try{ URL.revokeObjectURL(S.curAudio.src); }catch(e){} S.curAudio=null; }
}

args.new_string:
// 現在再生中（Web Speech / OpenAI音声）を「完了」させるresolver。割り込みや
// キュー直列化のために、再生終了・エラー・stopSpeaking のいずれでも解放する。
let _curRelease=null;

// ブラウザ内蔵音声（Web Speech）。awaitで発話終了まで待てる（キュー直列化のため）。
function webSpeak(text){
  return new Promise((resolve)=>{
    if(!S.tts || !window.speechSynthesis){ resolve(); return; }
    let settled=false;
    const done=()=>{ if(settled)return; settled=true; speaking=false; ignoreUntil=Date.now()+700; if(_curRelease===done)_curRelease=null; resolve(); };
    try{
      const u=new SpeechSynthesisUtterance(stripParens(text));
      const langKey=S.lang==="ja"?"ja":"en";
