  try{ if(window.speechSynthesis) speechSynthesis.cancel(); }catch(e){}
  if(S.curAudio){ try{ S.curAudio.pause(); }catch(e){} S.curAudio=null; }
  if(_curRelease){ const r=_curRelease; _curRelease=null; r(); }
