// Blobを再生。再生「終了」で解決（キュー直列化のため）。onStartは再生開始時に呼ぶ
// （play-start計測用）。stopSpeaking/割り込み時も _curRelease 経由で完了扱いにする。
function playBlob(blob, onStart){
  return new Promise((resolve,reject)=>{
    const a=new Audio(URL.createObjectURL(blob));
    S.curAudio=a; speaking=true;
    let settled=false, started=false;
    const end=(ok)=>{
      if(settled) return; settled=true;
      speaking=false; ignoreUntil=Date.now()+700;
      if(S.curAudio===a){ S.curAudio=null; }
      if(_curRelease===doRelease) _curRelease=null;
      try{ URL.revokeObjectURL(a.src); }catch(e){}
      ok ? resolve() : reject(new Error("audio play failed"));
    };
    const doRelease=()=>end(true);   // stopSpeaking/割り込み → 正常完了扱い（フォールバックしない）
    _curRelease=doRelease;
    a.onplaying=()=>{ if(!started){ started=true; if(onStart) onStart(); } };
    a.onended=()=>end(true);
    a.onerror=()=>end(false);
    a.play().catch(()=>end(false));
  });
}

