// 認識結果が「自分のTTSのエコー」か判定（バージイン時に自分の声を拾わないため）
function isEcho(transcript){
  const norm=s=>String(s||"").toLowerCase().replace(/[\s、。,.!！?？「」]/g,"");
  const bot=norm(S._botText), t=norm(transcript);
  if(!bot || !t) return false;
