import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
for (const line of readFileSync(".env", "utf8").split("\n")) {
  const m = /^([A-Z_]+)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}
const express = (await import("express")).default;
const { generateAndWriteToken } = await import("./server/api/auth/token.js");
const navChatRoutes = (await import("./server/api/routes/navChat.js")).default;
const ttsRoutes = (await import("./server/api/routes/tts.js")).default;
await generateAndWriteToken(join(tmpdir(), `self-${Date.now()}.token`), "probe-bearer-key-0123456789abcdef");
const app = express(); app.use(express.json()); app.use(navChatRoutes); app.use(ttsRoutes);
const server = app.listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as { port: number }).port;
const base = `http://127.0.0.1:${port}`;

// 1) self-provision both tokens
const prov = await fetch(`${base}/api/nav-view-tokens`, { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" });
const { ttsToken, navChatToken } = (await prov.json()) as { ttsToken: string; navChatToken: string };
console.log("provision:", prov.status, "ttsToken?", !!ttsToken, "navChatToken?", !!navChatToken);

// 2) use navChatToken on /api/nav-chat
const chat = await fetch(`${base}/api/nav-chat`, { method: "POST", headers: { Authorization: `Bearer ${navChatToken}`, "Content-Type": "application/json" }, body: JSON.stringify({ message: "こんにちは", context: { lang: "ja" } }) });
console.log("nav-chat with self token:", chat.status, await chat.text());

// 3) use ttsToken on /api/tts
const tts = await fetch(`${base}/api/tts`, { method: "POST", headers: { Authorization: `Bearer ${ttsToken}`, "Content-Type": "application/json" }, body: JSON.stringify({ text: "テスト", model: "gpt-4o-mini-tts", voice: "nova" }) });
console.log("tts with self token:", tts.status, tts.headers.get("content-type"), (tts.headers.get("content-type") || "").includes("audio") ? (await tts.arrayBuffer()).byteLength + " bytes" : await tts.text());

// 4) cross-check: navChatToken must NOT work on /api/tts (audience separation)
const cross = await fetch(`${base}/api/tts`, { method: "POST", headers: { Authorization: `Bearer ${navChatToken}`, "Content-Type": "application/json" }, body: JSON.stringify({ text: "x" }) });
console.log("cross-audience (navChat token on /api/tts) → expect 401:", cross.status);
server.close();

