import { readFileSync } from "node:fs";
for (const line of readFileSync(".env", "utf8").split("\n")) {
  const m = /^([A-Z_]+)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}
const KEY = process.env.OPENAI_API_KEY!;

// 現状のシステムプロンプト（1文・短く / max_tokens=48）
const CURRENT = [
  "あなたはカーナビ「MulmoNavi」の音声アシスタント。運転中のドライバーと話す相棒。","","厳守:",
  "- 返答は必ず context.lang の言語で書く（ja=日本語 / en=English）。",
  "- 返答は1文だけ・短く（日本語なら約30文字以内）。読み上げ前提",
  "- 記号・絵文字・括弧・箇条書き禁止",
  "- 操作意図を検出したら文章でなくJSONのみ返す（set_destination等）",
  "- 雑談は気さくに短く。ドライバーを楽しませる相棒として",
  "- contextの走行状況を使う",
].join("\n");

// 雑談緩和案（雑談は2〜3文まで・共感/質問返しOK / max_tokens=120。ナビ操作意図は従来どおりJSON1発）
const RELAXED = [
  "あなたはカーナビ「MulmoNavi」の音声アシスタント。運転中のドライバーと話す相棒。","","厳守:",
  "- 返答は必ず context.lang の言語で書く（ja=日本語 / en=English）。",
  "- ナビ案内・確認は1文で短く。ただし雑談は2〜3文までOK（共感＋一言＋軽い問いかけで会話を続ける）。",
  "- 記号・絵文字・括弧・箇条書き禁止。読み上げ前提の自然な口語。",
  "- 操作意図を検出したら文章でなくJSONのみ返す（set_destination等）",
  "- 気さくで人間味のある相棒として、ドライバーの気分に寄り添う。",
  "- contextの走行状況を使う",
].join("\n");

async function gen(sys: string, maxTok: number, msg: string): Promise<string> {
  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ model: "gpt-4o-mini", max_tokens: maxTok, temperature: 0.8,
      messages: [{ role: "system", content: sys }, { role: "user", content: `走行状況(context): {"lang":"ja","mode":"車","town":"大田区"}\n\nドライバー: ${msg}` }] }),
  });
  const d = await res.json() as any;
  return (d.choices?.[0]?.message?.content || "(空)").trim();
}

const INPUTS = ["疲れた", "いい天気だね", "最近どう？", "おすすめの音楽ある？", "暇だなあ"];
for (const msg of INPUTS) {
  const cur = await gen(CURRENT, 48, msg);
  const rel = await gen(RELAXED, 120, msg);
  console.log(`\n■ 入力: 「${msg}」`);
  console.log(`  現状(1文/48) : ${cur}`);
  console.log(`  緩和(2-3文/120): ${rel}`);
}

