args.content:
import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
for (const line of readFileSync(".env", "utf8").split("\n")) {
  const m = /^([A-Z_]+)=(.*)$/.exec(line.trim());
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
}
const express = (await import("express")).default;
const { generateAndWriteToken } = await import("./server/api/auth/token.js");
const { mintNavChatToken } = await import("./server/api/auth/viewToken.js");
const navChatRoutes = (await import("./server/api/routes/navChat.js")).default;
await generateAndWriteToken(join(tmpdir(), `relax-${Date.now()}.token`), "probe-bearer-key-0123456789abcdef");
const minted = mintNavChatToken("voice-nav")!;
const app = express(); app.use(express.json()); app.use(navChatRoutes);
const server = app.listen(0, "127.0.0.1");
await new Promise((r) => server.once("listening", r));
const port = (server.address() as { port: number }).port;
const url = `http://127.0.0.1:${port}/api/nav-chat`;
const auth = { Authorization: `Bearer ${minted.token}`, "Content-Type": "application/json" };
const ctx = { lang: "ja", town: "大田区", dest: "男体山", etaMin: 42, mode: "車", navOn: true };
function sentences(s: string) { return (s.match(/[。！？!?]/g) || []).length || 1; }
async function call(cat: string, message: string) {
  const res = await fetch(url, { method: "POST", headers: auth, body: JSON.stringify({ message, context: ctx }) });
  const d = await res.json() as any;
  if (d.action) { console.log(`[${cat}] 「${message}」→ action ${JSON.stringify(d)}`); return; }
  const r = d.reply || "";
  console.log(`[${cat}] 「${message}」→ (${sentences(r)}文/${[...r].length}字) ${r}`);
}
console.log("=== 雑談（2〜3文になるべき） ===");
for (const m of ["疲れた", "いい天気だね", "暇だなあ", "おすすめの音楽ある？"]) await call("雑談", m);
console.log("\n=== ナビ実務（1文で短いままであるべき） ===");
for (const m of ["あとどれくらいで着く？", "今どこ走ってる？", "ナビ開始して"]) await call("ナビ", m);
console.log("\n=== アクション（短いJSONのまま） ===");
for (const m of ["東京駅", "セブン寄って"]) await call("action", m);
server.close();
